import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {campaign,core,mp,bindings,attrs,element} from './app-harness.mjs';
import {S,same,ui,flush} from './deposit-save-harness.mjs';
import {serviceSaveGate} from './service-save-harness.mjs';
import {SaveNotCommittedError,SaveCommittedPublicationError} from '../js/persistence.mjs';
import * as A from '../js/amounts.mjs';

// Actual app callbacks/controller/state/rules/Store, isolated synthetic storage.
// Extend exposure/counting only, never any production function body or shared
// harness. Native DOM, Web Locks, geometry and gestures belong to browser CI.
const harnessURL=new URL('./app-harness.mjs',import.meta.url),storageURL=new URL('./deposit-save-harness.mjs',import.meta.url);
const app=await readFile(new URL('../js/app.mjs',import.meta.url),'utf8');
const marker='store=new Store(receiveCampaign,',roleStart=app.indexOf(marker);assert.ok(roleStart>=0);
const roleCallback=app.slice(roleStart+marker.length).split(');try{state=store.read();}')[0];assert.ok(roleCallback.startsWith('(editable,text)=>'));
const absolutize=(source,url)=>source.replaceAll('import.meta.url',JSON.stringify(url.href)).replace(/from '(\.[^']+)'/g,(_all,path)=>'from '+JSON.stringify(new URL(path,url).href));
function replace(source,from,to){assert.ok(source.includes(from),'Expected actual harness boundary '+from);return source.replace(from,to);}
let hs=absolutize(await readFile(harnessURL,'utf8'),harnessURL);
hs=replace(hs,'globalThis.api={setStore','globalThis.api={completePurchaseWrite:typeof completePurchaseWrite===\'function\'?completePurchaseWrite:null,get saleQuotes(){return saleQuotes;},get saleTaxDice(){return saleTaxDice;},get editSale(){return editSale;},setEditSale(value){editSale=value;},get selectedSet(){return selected;},setPreviewSale(value){previewSale=value;},roleChange:'+roleCallback+',setStore');
hs=replace(hs,'priceDice:0','priceDice:0,insuranceQuotes:0');
hs=replace(hs,'die:()=>3','die:()=>3,insuranceQuote(...args){calls.insuranceQuotes++;return bindings.R.insuranceQuote(...args);}');
const hm='data:text/javascript;base64,'+Buffer.from(hs).toString('base64');
let ss=absolutize(await readFile(storageURL,'utf8'),storageURL);ss=replace(ss,JSON.stringify(harnessURL.href),JSON.stringify(hm));
const {depositHarness}=await import('data:text/javascript;base64,'+Buffer.from(ss).toString('base64'));
const success=/Purchase: Synthetic cargo saved\./;
function fixture({insurance=true,local=false,illegal=false,creditStep=1,huge=false,fractional=false,price='1001',zones=false}={}){
 const s=campaign();s.bank=huge?'9007199254740993123456789':'1000000';s.ship.capacity='100';s.settings={...s.settings,insurance,creditStep};
 const world=bindings.R.context(s.worlds[s.actual],core),options={skill:1,counterparty:2,local,side:'buy',creditStep};
 const faces=[5,5,2],quote=bindings.R.quote(core.commodities.find(g=>g.id==='11'),world,options,core,()=>faces.shift());
 s.snapshots=[{id:'supplier',kind:'supplier',worldId:s.actual,world,party:'synthetic|supplier',partyName:'Synthetic supplier',hours:0,startedHours:0,success:true,options,offers:[{id:'offer',commodity:'11',description:'Synthetic cargo',remaining:fractional?'1.5':'6',expired:false,illegal,...quote,unitPrice:huge?'90071992547409931234567':price,overrides:[{reason:'Saved manual price',before:{unitPrice:quote.unitPrice},after:{unitPrice:price}}]}]}];
 if(zones){const w={...s.worlds['1,0'],id:'2,0',x:2,name:'Second amber stop',zone:'Amber'};s.worlds['1,0'].zone='Amber';s.worlds[w.id]=w;s.worlds['8,0'].zone='Red';s.route=[s.actual,'1,0','2,0','8,0'];}
 return S.validate(s);
}
function setup(saved=fixture()){
 const h=depositHarness(saved,{setTimeout:()=>0,clearTimeout(){}}),form=h.dom.ids.get('modal-form'),query=form.querySelectorAll;
 form.querySelectorAll=selector=>selector==='input,select,textarea,button'?[...h.dom.fields().values(),...modalButtons(h),h.dom.ids.get('modal-submit'),h.dom.ids.get('modal-cancel')]:query(selector);
 h.store.onRole=(editable,text)=>{h.roles.push([editable,text]);h.hooks.onRole?.(editable,text);h.api.roleChange(editable,text);};return h;
}
function modalButtons(h){return [...h.dom.ids.get('modal-body').innerHTML.matchAll(/<button\b([^>]*)>/g)].map(m=>element(attrs(m[1])));}
async function prepare(h,edits={}){h.api.buyForm('offer');h.fill({quantity:1,fee:5,description:'Synthetic cargo',...edits});h.api.stagePurchase();assert.equal(ui(h).modalTitle,'Review purchase · Synthetic cargo');assert.equal(ui(h).modalError,'');}
const count=h=>({quotes:h.calls.quotes,priceDice:h.calls.priceDice,insuranceQuotes:h.calls.insuranceQuotes});
const body=h=>h.dom.ids.get('modal-body').innerHTML;
const display=h=>({summary:h.dom.ids.get('summary').innerHTML,main:h.dom.ids.get('main').innerHTML});
const submitEvent=h=>({preventDefault(){},currentTarget:h.dom.ids.get('modal-form')});
const noSuccess=h=>assert.doesNotMatch(ui(h).message,success);
function terminal(h){assert.equal(h.store.reloadRequired,true);assert.equal(h.store.editable,false);assert.equal(h.dom.ids.get('takeover').disabled,true);assert.match(h.dom.ids.get('save-status').textContent,/reload/i);noSuccess(h);if(ui(h).modalOpen){assert.equal(ui(h).submitDisabled,true);assert.match(ui(h).modalError,/reload/i);}}
function canonical(state){const ids=new Map();return JSON.parse(JSON.stringify(state).replace(/[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}/gi,id=>{if(!ids.has(id))ids.set(id,'generated-'+ids.size);return ids.get(id);}));}
function exact(h,before,entry){same(h.persisted(),entry.args[0]);same(h.api.state,entry.args[0]);assert.equal(h.bytes(),JSON.stringify(entry.args[0]));assert.equal(h.persisted().revision,before.revision+1);assert.equal(h.persisted().undo.length,before.undo.length+1);assert.equal(h.counters.writes,1);assert.equal(entry.args[1],before.revision);assert.ok(entry.args[2]);assert.doesNotMatch(h.bytes(),/saveToken|replacementToken/);}
async function pending(t,h=setup(),edits={}){
 const before=structuredClone(h.api.state),raw=h.bytes();await prepare(h,edits);
 const rounding=structuredClone(h.api.inputRounding),counts=count(h),session=h.api.modalSession,review=body(h),gate=serviceSaveGate(h.store),detached=h.dom.ids.get('modal-form').onsubmit,operation=h.submit();
 await flush();assert.equal(gate.entries.length,1,'One production PURCHASE COMMIT reached the delayed provider');
 t.after(async()=>{for(const e of gate.entries)if(!e.settled)e.fulfill();await operation;gate.restore();});return {h,before,raw,rounding,counts,session,review,gate,detached,operation};
}
function dispatch(h,name,arg=''){const b={disabled:false,dataset:{action:name,arg},closest:selector=>selector==='[data-action]'?b:null};h.dom.dispatch('click',b,{preventDefault(){}});return b;}

// Baseline-red assertions are intentionally behavioral, not helper-name checks.
test('delayed purchase freezes Close before write and retains the exact visible review through publication and settlement',async t=>{
 const {h,before,raw,session,review,rounding,counts,gate,operation}=await pending(t),visible=display(h);
 assert.equal(h.bytes(),raw);assert.equal(session.busy,true);assert.equal(session.awaitSave,true);assert.equal(ui(h).submitDisabled,true);assert.equal(h.dom.ids.get('modal-close').disabled,true);noSuccess(h);
 gate.entries[0].write();exact(h,before,gate.entries[0]);same(count(h),counts);same(h.api.inputRounding,rounding);assert.equal(body(h),review);assert.equal(h.api.modalSession,session);assert.equal(ui(h).modalOpen,true);noSuccess(h);same(display(h),visible);h.api.render();same(display(h),visible);
 gate.entries[0].fulfill();await operation;assert.equal(ui(h).modalOpen,false);assert.equal(ui(h).modalError,'');assert.match(ui(h).message,success);same(count(h),counts);for(const observation of h.trace)assert.doesNotMatch(observation.message,success);
});
test('unclassified purchase rejection requires reload and cannot re-enable COMMIT PURCHASE',async t=>{const {h,raw,gate,operation}=await pending(t);gate.entries[0].reject();await operation;terminal(h);assert.equal(h.bytes(),raw);assert.equal(h.counters.writes,0);});
test('purchase publication alone never exposes saved cargo or a changed bank',async t=>{const {h,gate,operation}=await pending(t),visible=display(h);gate.entries[0].write();same(display(h),visible);noSuccess(h);assert.equal(ui(h).modalOpen,true);gate.entries[0].fulfill();await operation;assert.notDeepEqual(display(h),visible);});

for(const insured of [false,true])test(`native ${insured?'insured':'uninsured'} completion publishes, closes and announces in the initiating stack`,async()=>{
 const h=setup(),before=h.persisted();await prepare(h,{insure:insured});const counts=count(h),operation=h.submit();assert.equal(h.counters.writes,1);assert.equal(ui(h).modalOpen,false);assert.match(ui(h).message,success);assert.equal(ui(h).modalError,'');same(count(h),counts);await operation;assert.equal(h.persisted().policies.length,Number(insured));assert.equal(h.persisted().revision,before.revision+1);
});
test('raw purchase completion preserves the native non-Promise contract',async()=>{const h=setup();await prepare(h);assert.equal(typeof h.api.completePurchaseWrite,'function');const result=h.api.completePurchaseWrite(h.api.modalSession.purchaseOwner);assert.notEqual(typeof result?.then,'function');assert.equal(h.counters.writes,1);assert.equal(ui(h).modalOpen,false);assert.match(ui(h).message,success);});

const ceil=(value,step=1)=>{const rational=A.dec(A.div(value,step));return String((-A.floor({n:-rational.n,d:rational.d}))*BigInt(step));};
const material=state=>Object.fromEntries(Object.entries(state).filter(([key])=>!['revision','events','jumpAttempts'].includes(key)));
function specification(before,edits={}){
 const offer=before.snapshots[0].offers[0],step=before.settings.creditStep,quantity=ceil(edits.quantity??1),feePercent=Number(edits.fee??5),goods=ceil(A.mul(quantity,offer.unitPrice),step),fee=ceil(A.mul(goods,A.div(feePercent,100)),step);let insurance=null;
 if(edits.insure){const route=before.route.slice(before.routeIndex,before.routeIndex+Number(edits.insuranceLegs??before.route.length-before.routeIndex-1)+1),plannedDistance=route.slice(1).reduce((sum,id,i)=>sum+bindings.M.distance(before.worlds[route[i]],before.worlds[id]),0),distance=Number(edits.insuranceDistance??plannedDistance),premium=edits.manualPremium?ceil(edits.manualPremium,step):null;insurance={...bindings.R.insuranceQuote(goods,Number(edits.coverage??70),distance,route.map(id=>before.worlds[id].zone),mp,premium,step),route,destination:route.at(-1),routeProgress:0,plannedDistance,distanceOverrideReason:distance!==plannedDistance?edits.distanceReason:null};}
 return {goods,fee,total:String(BigInt(goods)+BigInt(fee)+BigInt(insurance?.premium??0)),args:{snapshotId:'supplier',offerId:'offer',quantity,feePercent,description:'Synthetic cargo',insurance}};
}
const economics=[
 {name:'uninsured partial with manual fee',options:{insurance:false},edits:{quantity:2,fee:7},expected:{goods:'2002',fee:'141',premium:'0',total:'2143'}},
 {name:'full saved offer without fee',options:{},edits:{quantity:6,fee:0},expected:{goods:'6006',fee:'0',premium:'0',total:'6006'}},
 {name:'table insurance and one atomic fee',options:{},edits:{quantity:2,fee:10,insure:true},expected:{goods:'2002',fee:'201',premium:'161',total:'2364'}},
 {name:'zero manual premium retains insured policy and zero premium ledger row',options:{},edits:{quantity:1,fee:0,insure:true,manualPremium:'0'},expected:{goods:'1001',fee:'0',premium:'0',total:'1001'}},
 {name:'Cr100 tons and manual premium rounding',options:{creditStep:100},edits:{quantity:'1.1',fee:7,insure:true,manualPremium:'101.1'},expected:{goods:'2100',fee:'200',premium:'200',total:'2500'}},
 {name:'Cr1 fractional saved price remains exact until goods rounding',options:{price:'1000.1'},edits:{quantity:3,fee:7},expected:{goods:'3001',fee:'211',premium:'0',total:'3212'}},
 {name:'huge credit strings exceed floating point precision',options:{huge:true},edits:{quantity:2,fee:7,insure:true,manualPremium:'901'}},
 {name:'selected route prefix deduplicates Amber and excludes later Red',options:{zones:true},edits:{quantity:2,fee:0,insure:true,insuranceLegs:2,insuranceDistance:2}},
 {name:'manual distance reason and premium retained without recalculation',options:{zones:true},edits:{quantity:1,fee:0,insure:true,insuranceLegs:1,insuranceDistance:8,distanceReason:'Referee corridor',manualPremium:'501.1'}},
 {name:'partial fractional offer leaves its ordinary remainder',options:{fractional:true},edits:{quantity:1,fee:0},expected:{goods:'1001',fee:'0',premium:'0',total:'1001'}}
];
for(const delayed of [false,true])for(const scenario of economics)test(`${delayed?'delayed':'native'} purchase economics: ${scenario.name}`,async()=>{
 const h=setup(fixture(scenario.options)),before=h.persisted(),spec=specification(before,scenario.edits);await prepare(h,scenario.edits);const rounding=structuredClone(h.api.inputRounding),counts=count(h),review=body(h),gate=delayed?serviceSaveGate(h.store):null,operation=h.submit();
 if(gate){assert.equal(gate.entries.length,1);gate.entries[0].write();same(count(h),counts);assert.equal(body(h),review);gate.entries[0].fulfill();}await operation;gate?.restore();const saved=h.persisted(),lot=saved.lots[0],policy=saved.policies[0];
 assert.equal(h.counters.writes,1);assert.equal(ui(h).modalError,'');assert.equal(ui(h).modalOpen,false);assert.match(ui(h).message,success);assert.equal(saved.bank,String(BigInt(before.bank)-BigInt(spec.total)));assert.equal(lot.quantity,spec.args.quantity);assert.equal(lot.goodsValue,spec.goods);assert.equal(lot.basis,spec.total);assert.equal(saved.snapshots[0].offers[0].remaining,A.decimal(A.sub(before.snapshots[0].offers[0].remaining,spec.args.quantity)));
 same(lot.audit.price,before.snapshots[0].offers[0]);same(lot.audit.price.audit.dice,{dice:[5,5,2],total:12});assert.equal(lot.audit.price.audit.tradeComplication.result,'complication');same(count(h),counts);assert.equal(counts.quotes,0);assert.equal(counts.priceDice,0);
 const purchase=saved.ledger.filter(e=>e.type==='Purchase');assert.equal(purchase.length,1);assert.equal(purchase[0].amount,String(-BigInt(spec.goods)));same(purchase[0].purchase,{commodity:'11',description:'Synthetic cargo',quantity:spec.args.quantity,unitPrice:before.snapshots[0].offers[0].unitPrice,fee:spec.fee,premium:spec.args.insurance?.premium??'0',priceAudit:before.snapshots[0].offers[0].audit});
 for(const [type,amount]of [['Broker fee',spec.fee],['Insurance premium',spec.args.insurance?.premium??'0']]){const records=saved.ledger.filter(e=>e.type===type);assert.equal(records.length,type==='Insurance premium'?Number(!!spec.args.insurance):Number(BigInt(amount)>0n));if(records.length)assert.equal(records[0].amount,String(-BigInt(amount)));}
 if(policy){for(const [key,value]of Object.entries(spec.args.insurance))same(policy[key],value);assert.equal(policy.lotId,lot.id);assert.equal(policy.insuredValue,spec.goods);assert.equal(policy.remainingValue,spec.goods);assert.equal(policy.initialQuantity,spec.args.quantity);same(policy.claims,[]);same(policy.amendments,[]);assert.equal(policy.status,'active');}
 if(scenario.expected){for(const [key,value]of Object.entries(scenario.expected))assert.equal(key==='premium'?spec.args.insurance?.premium??'0':spec[key],value,'Independent '+key+' calculation');}
 const expected=S.transition(before,'Purchase: Synthetic cargo',next=>{S.buy(next,spec.args);if(rounding.length)next.events.push({id:S.uid(),label:'Rounding applied [R]',hours:next.hours,roundingStep:before.settings.creditStep,roundingChanges:rounding});});same(canonical(saved),canonical(expected));
 for(const key of ['hours','actual','route','routeIndex','contracts','trader','settings','ship'])same(saved[key],before[key]);assert.match(h.api.historyPanel(),/Purchase: Synthetic cargo/);h.api.ledgerAudit(purchase[0].id);assert.match(body(h),/Synthetic cargo/);assert.match(body(h),/complication/i);h.api.closeModal();
 const fresh=setup(h.store.read());same(fresh.persisted(),saved);await fresh.runAction('undo');same(material(fresh.persisted()),material(before));
 if(delayed){const sync=setup(before);await prepare(sync,scenario.edits);await sync.submit();same(canonical(saved),canonical(sync.persisted()),'Delayed full campaign equals native purchase, including inverse data and audit');}
});
for(const {local,illegal,expected}of [{local:false,illegal:false,expected:0},{local:false,illegal:true,expected:0},{local:true,illegal:false,expected:10},{local:true,illegal:true,expected:20}])test(`existing local fee defaults remain ${expected}% for local=${local}, illegal=${illegal}`,async()=>{const h=setup(fixture({local,illegal}));h.api.buyForm('offer');assert.equal(h.dom.fields().get('fee').value,String(expected));await h.submit();await h.submit();assert.equal(h.persisted().lots[0].audit.fee,ceil(A.mul('1001',A.div(expected,100))));assert.equal(h.calls.priceDice,0);});
