 h.failNext();const first=h.submit();if(gate)gate.entries[0].fulfill();await first;assert.equal(h.bytes(),raw);assert.equal(h.counters.writes,0);assert.match(ui(h).modalError,/quota/);assert.equal(ui(h).submitDisabled,false);assert.equal(h.store.reloadRequired??false,false);assert.equal(owner.pending,false);same(owner.args,accepted);same(h.api.inputRounding,rounding);same(count(h),counts);assert.equal(body(h),review);h.api.render();
