for(const mode of ['same revision disk change','unreadable durable campaign'])for(const phase of ['before submit','typed unwritten result'])test(`${mode} ${phase} retires review without treating it as consent to changed terms`,async()=>{
 const h=setup();await prepare(h);const gate=serviceSaveGate(h.store),detached=h.dom.ids.get('modal-form').onsubmit;let operation;
 if(phase==='typed unwritten result'){operation=h.submit();assert.equal(gate.entries.length,1);}
 if(mode==='same revision disk change'){const next=h.persisted();next.bank='999993';h.external(next,{publish:false});}else h.store.read=()=>{throw Error('Injected unreadable durable campaign');};const raw=h.bytes();
 if(operation){gate.entries[0].reject(new SaveNotCommittedError(Error('Known unwritten purchase')));await operation;}else await h.submit();
 assert.equal(h.bytes(),raw);assert.equal(h.counters.writes,0);terminal(h);assert.match(ui(h).message,/not saved/i);assert.doesNotMatch(ui(h).message,/outcome.*could not be confirmed/i);await detached(submitEvent(h));assert.equal(gate.entries.length,phase==='before submit'?0:1);assert.equal(h.bytes(),raw);gate.restore();
});
